import React from "react";
import { CheckCircle } from "lucide-react";

/*
  COMMAND TREE RENDERER
  parent → children
  deterministic layout
*/

const CryptoFlow = ({ currentStep = 0, mode = "hybrid" }) => {
  
  // ================= DATA MODEL =================

  const hybridTree = [
    {
      title: "Ephemeral Agreement",
      sub: "X25519",
      children: ["Generate key", "Exchange values"],
    },
    {
      title: "Encapsulate",
      sub: "Kyber",
      children: ["Shared secret", "Ciphertext"],
    },
    {
      title: "HKDF",
      sub: "SHA-256",
      children: ["Mix salt", "Expand key"],
    },
    {
      title: "AES Encrypt",
      sub: "GCM",
      children: ["Encrypt", "Tag"],
    },
    {
      title: "Upload",
      sub: "MinIO",
      children: ["Pack", "Store"],
    },
  ];

  const rsaTree = [
    {
      title: "Keypair",
      sub: "RSA-2048",
      children: ["Public key", "Private key"],
    },
    {
      title: "Padding",
      sub: "OAEP",
      children: ["Prepare"],
    },
    {
      title: "Encrypt",
      sub: "Mod Exp",
      children: ["Cipher"],
    },
    {
      title: "Build Blob",
      sub: "Meta",
      children: ["Headers"],
    },
    {
      title: "Upload",
      sub: "MinIO",
      children: ["Store"],
    },
  ];

  const phases = mode === "hybrid" ? hybridTree : rsaTree;

  // ================= COLORS =================

  const accent =
    mode === "hybrid"
      ? "text-neon-green border-neon-green"
      : "text-purple-400 border-purple-400";

  const line =
    mode === "hybrid"
      ? "bg-neon-green"
      : "bg-purple-400";

  // ================= RENDER =================

  return (
    <div className="bg-black/40 p-10 rounded-xl border border-scifi-border overflow-x-auto">

      <div className="flex justify-between relative min-w-[900px]">

        {/* BASE LINE */}
        <div className="absolute top-6 left-0 w-full h-[2px] bg-gray-800"></div>

        {/* PROGRESS */}
        <div
          className={`absolute top-6 left-0 h-[2px] ${line}`}
          style={{
            width: `${(Math.max(currentStep - 1, 0) / (phases.length - 1)) * 100}%`,
          }}
        />

        {phases.map((phase, i) => {
          const done = currentStep >= i + 1;
          const branchUp = i % 2 === 1; // alternate

          return (
            <div key={i} className="relative z-10 flex flex-col items-center w-48">

              {/* ================= PARENT ================= */}
              <div
                className={`w-14 h-14 rounded-full border-2 bg-black flex items-center justify-center transition-all duration-500
                ${done ? accent : "border-gray-700 text-gray-700"}`}
              >
                {done ? (
                  <CheckCircle size={18} />
                ) : (
                  <div className="w-2 h-2 bg-gray-600 rounded-full" />
                )}
              </div>

              {/* TITLE */}
              <div className="mt-2 text-center">
                <p className={`text-[11px] font-bold ${done ? "text-white" : "text-gray-600"}`}>
                  {phase.title}
                </p>
                <p className="text-[10px] text-gray-500 font-mono">{phase.sub}</p>
              </div>

              {/* ================= CHILDREN ================= */}
              <div
                className={`absolute flex flex-col items-center ${
                  branchUp ? "-top-24" : "top-24"
                }`}
              >
                {phase.children.map((child, k) => {
                  const offset =
                    (k - (phase.children.length - 1) / 2) * 70;

                  return (
                    <div
                      key={k}
                      className="absolute flex flex-col items-center"
                      style={{ transform: `translateX(${offset}px)` }}
                    >
                      {/* connector */}
                      <div
                        className={`w-[2px] ${
                          done ? line : "bg-gray-800"
                        } ${branchUp ? "h-16" : "h-16"}`}
                      />

                      {/* node */}
                      <div
                        className={`w-6 h-6 rounded-full border mt-1 ${
                          done ? accent : "border-gray-700"
                        } bg-black`}
                      />

                      {/* label */}
                      <p
                        className={`mt-2 text-[10px] font-mono whitespace-nowrap ${
                          mode === "hybrid"
                            ? "text-neon-green"
                            : "text-purple-300"
                        }`}
                      >
                        {child}
                      </p>
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default CryptoFlow;
